<script setup lang="ts">
import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import Empty from '../components/common/Empty.vue';import RankingTable from '../components/RankingTable.vue';import WeightBars from '../components/WeightBars.vue';import DistancePlot from '../components/DistancePlot.vue';import SensitivityChart from '../components/SensitivityChart.vue';import SimulationTable from '../components/SimulationTable.vue';import JudgmentGrid from '../components/JudgmentGrid.vue';import {create as createRun} from '../api/runs';import {useAsync} from '../hooks/useAsync';import {number} from '../utils/format';
const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();
const selected=ref(''),estimate=ref(''),samples=ref(500),seed=ref(20261114);
const run=computed(()=>props.data.runs.find(r=>r.id===selected.value)||props.data.runs[0]);
const datasetId=computed(()=>{const c=props.data.criteria.find(c=>c.id===props.data.judgments.find(j=>j.id===run.value?.judgment_id)?.criteria_set_id);return c?.dataset_id});
const estimates=computed(()=>props.data.estimates.filter(e=>e.dataset_id===datasetId.value));
const activeEstimate=computed(()=>estimates.value.find(e=>e.id===estimate.value)||estimates.value[0]);
const {busy,error,execute}=useAsync();
async function launch(){if(!run.value||!activeEstimate.value)return;await execute(async()=>{const created=await createRun({judgment_id:run.value!.judgment_id,estimate_id:activeEstimate.value!.id,samples:samples.value,seed:seed.value});selected.value=created.id;await props.refresh()})}
</script>
<template>
<PageHeading code="06 / RANK & SENSITIVITY" title="先看一致性，再看名次能否站住。" description="高CR警告不被隐藏。无辨识力的指标或距离退化不硬排名，抽样首名占比不是确定性保证。"/>
<div class="run-selector"><label>计算记录<select aria-label="选择计算记录" :value="run?.id" @change="selected=($event.target as HTMLSelectElement).value"><option v-for="r in data.runs" :key="r.id" :value="r.id">{{data.judgments.find(j=>j.id===r.judgment_id)?.name}} · {{r.created_at.slice(11,19)}}{{r.estimate_id?' · 抽样':''}}</option></select></label><Status v-if="run" :value="run.status"/></div>
<Empty v-if="!run">先保存指标方向和原始判断矩阵，再运行后台权衡。</Empty>
<Notice v-else-if="run.status!=='completed'" :error="run.status==='failed'">{{run.status==='failed'?run.error:'独立worker正在计算，页面会自动刷新。'}}</Notice>
<template v-else>
<Notice v-if="run.result.ahp.cr_warning" error>CR={{number(run.result.ahp.cr,4)}}高于声明阈值{{number(run.result.ahp.threshold,2)}}。原矩阵完整保留，请复核循环矛盾；系统没有自动改值。</Notice>
<section class="paper" v-if="canWrite&&estimates.length"><div class="section-heading"><h2>按区间估计抽样首名</h2><span>权重固定，不重新判断AHP</span></div><form class="grid-form" @submit.prevent="launch"><label>区间估计<select aria-label="抽样区间估计" :value="activeEstimate?.id" @change="estimate=($event.target as HTMLSelectElement).value"><option v-for="e in estimates" :key="e.id" :value="e.id">{{e.name}}</option></select></label><label>样本量<input aria-label="样本量" type="number" min="1" max="10000" step="1" v-model.number="samples"/></label><label>随机种子<input aria-label="随机种子" type="number" min="0" max="2147483647" step="1" v-model.number="seed"/></label><button :disabled="busy||!activeEstimate">{{busy?'正在排队…':'运行抽样　→'}}</button></form><p class="caption">每次抽样按三角分布独立取每航段每指标，再重算全体航段的归一化与理想点；相同种子与样本量可复现，重排航段顺序不改变各航段计数。超时则保留部分结果并标明实际完成样本数。</p><Notice v-if="error" error>{{error}}</Notice></section>
<Notice v-if="run.result.simulation&&run.result.simulation.status==='partial'" error>抽样在{{number(run.result.simulation.elapsed_seconds,1)}}秒时超时，声明{{run.result.simulation.requested_samples}}个样本，实际完成{{run.result.simulation.completed_samples}}个。以下占比均以实际完成样本为分母，不能当作全部样本的结果。</Notice>
<section class="paper" v-if="run.result.simulation"><div class="section-heading"><h2>每条航段的首名次数与占比</h2><span>{{run.result.simulation.estimate_name}} / 种子{{run.result.simulation.seed}}</span></div><div class="result-metrics"><div><small>声明样本</small><b>{{run.result.simulation.requested_samples}}</b></div><div><small>实际完成样本</small><b>{{run.result.simulation.completed_samples}}</b></div><div><small>不可排名样本</small><b>{{run.result.simulation.unavailable_samples}}</b></div><div><small>抽样用时（秒）</small><b>{{number(run.result.simulation.elapsed_seconds,1)}}</b></div></div><SimulationTable :simulation="run.result.simulation"/><p class="caption">合计列应等于实际完成样本数。独占、并列、未获首名与不可排名互斥且覆盖全部已完成样本；退化样本不丢弃，计入不可排名。占比是抽样频率，不是确定性保证。</p><details class="audit-details"><summary>抽样依据 / 归档保留</summary><div class="table-scroll"><table><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>抽样分布</td><td>{{run.result.simulation.distribution}}</td></tr><tr><td>独立流</td><td>{{run.result.simulation.stream_key}}</td></tr><tr><td>权重与归一</td><td>{{run.result.simulation.weights_rule}}</td></tr><tr><td>退化样本</td><td>{{run.result.simulation.degenerate_rule}}</td></tr><tr><td>依据校验码</td><td><small>{{run.result.simulation.basis_checksum}}</small></td></tr></tbody></table></div><p class="caption">归档会在报告中保留同一份抽样依据。占比不能解释为航段必然获得首名的概率，也不构成航行安全或调度判定。</p></details></section>
<section class="paper"><div class="section-heading"><h2>AHP主特征向量与一致性</h2><span>幂迭代{{run.result.ahp.iterations}}次 / RI={{number(run.result.ahp.ri,2)}}</span></div><div class="result-metrics"><div><small>主特征值 λmax</small><b>{{number(run.result.ahp.lambda_max,4)}}</b></div><div><small>一致性指标 CI</small><b>{{number(run.result.ahp.ci,4)}}</b></div><div :class="{warning:run.result.ahp.cr_warning}"><small>一致性比率 CR</small><b>{{number(run.result.ahp.cr,4)}}</b></div><div><small>声明阈值</small><b>{{number(run.result.ahp.threshold,2)}}</b></div></div><WeightBars :criteria="run.result.criteria" :weights="run.result.ahp.weights"/><p class="caption">RI表：3=.58 / 4=.90 / 5=1.12 / 6=1.24。阈值只是讨论规则；特征残差{{run.result.ahp.eigen_residual.toExponential(2)}}。</p></section>
<Notice v-if="!run.result.topsis.available" error>{{run.result.topsis.reason}}<ul><li v-for="issue in run.result.topsis.issues" :key="issue.criterion_index">{{run.result.criteria[issue.criterion_index]?.label}}：{{issue.reason}}</li></ul></Notice>
<section class="paper"><h2>TOPSIS方案排序</h2><RankingTable :rows="run.result.alternatives"/></section>
<div class="evidence-grid" v-if="run.result.topsis.available"><section class="paper"><h2>到优、劣理想点的距离</h2><DistancePlot :rows="run.result.alternatives"/></section><aside class="definition-note"><span class="eyebrow">IDEAL POINT DISTANCE</span><h2>离优点更近，<br/>离劣点更远。</h2><p>列向量归一后按AHP权重加权。成本指标以最小值为优点，收益指标以最大值为优点。</p><p>贴近度 = 到劣点距离 /（到优点距离 + 到劣点距离）。并列贴近度保留并列名次。</p></aside></div>
<section class="paper" v-if="run.result.sensitivity.length"><div class="section-heading"><h2>单权重扰动的名次范围</h2><span>逐指标±{{Math.round(run.result.perturbation*100)}}% / {{run.result.sensitivity.length}}个确定性情景</span></div><SensitivityChart :rows="run.result.alternatives"/><p class="caption">线段为情景最小—最大名次，点为基准名次；每次只改一个权重，再把全部权重归一。不是联合扰动或概率区间。</p></section>
<section class="paper"><h2>保存的原始判断矩阵</h2><JudgmentGrid :matrix="run.result.matrix_original" :criteria="run.result.criteria"/></section>
<aside class="assumptions"><h2>判断规则与解释边界</h2><p v-for="(a,i) in run.result.assumptions" :key="a"><b>0{{i+1}}</b>{{a}}</p><small>输入校验码 {{run.result.checksum.slice(0,24)}}</small></aside>
</template>
</template>
